"""Bounded aggregate updates for the existing data-only draft writer.

No attachment fetching, acceptance, Git mutation or GitHub client is provided.
Generated regions are replaced only when their old bytes match the records;
owner prose outside those regions is retained exactly.
"""
import argparse
import base64
import binascii
import hashlib
import importlib.util
import json
from pathlib import Path
import re

MAX_RECORDS = 32
MAX_TOTAL_RECORDS = 4 * 1024 * 1024
MAX_DOCUMENT = 512 * 1024
LEGACY_15 = '2e0ede8ca75435f97b643806d80612579a52dd05'
LEGACY_15_BUNDLE = '1f353838bc9a83488a261f9f31adaa4baf33058fb3ffd7e0a269ef5b1e7ce817'


def load(name):
    """Load an adjacent trusted project module, not an uploaded module/path."""
    spec = importlib.util.spec_from_file_location('aggregate_' + name,
                                                 Path(__file__).with_name(name + '.py'))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def blob_id(raw):
    """Compute a Git blob identity without writing a Git object."""
    return hashlib.sha1(b'blob ' + str(len(raw)).encode() + b'\0' + raw).hexdigest()


def read_blob(api, row, core, limit):
    """Require bounded regular-file content matching the advertised Git blob."""
    core.need(row.get('type') == 'blob' and row.get('mode') == '100644' and
              re.fullmatch('[0-9a-f]{40}', row.get('sha', '')), 'AGGREGATE_BLOB')
    value = api.get('git/blobs/' + row['sha'])
    core.need(type(value) is dict and value.get('sha') == row['sha'] and
              value.get('encoding') == 'base64' and type(value.get('size')) is int and
              0 <= value['size'] <= limit and type(value.get('content')) is str and
              len(value['content']) <= 2 * limit + 16, 'AGGREGATE_BLOB')
    try:
        raw = base64.b64decode(value['content'].replace('\n', '').replace('\r', ''), validate=True)
    except (ValueError, binascii.Error):
        raise core.Refused('AGGREGATE_BLOB') from None
    core.need(len(raw) == value['size'] and blob_id(raw) == row['sha'], 'AGGREGATE_BLOB')
    return raw


def records(api, entries, version, core):
    """Read one release's typed records, with one explicitly pinned v1 bridge.

    Issue15's exact legacy blob/bundle was checked against its original share
    archive (PCI10de:2882). Adapt only that immutable record in memory; never
    rewrite it or infer PCI values for other v1 records.
    """
    pattern = re.compile(re.escape(core.ROOT) + r'(?:[A-Za-z0-9_]+/){1,2}' +
                         re.escape(version) + r'/issue-[1-9][0-9]*/record\.json')
    selected = []
    for row in entries:
        core.need(type(row) is dict, 'AGGREGATE_TREE')
        if type(row.get('path')) is str and pattern.fullmatch(row['path']):
            selected.append(row)
    core.need(len(selected) <= MAX_RECORDS, 'AGGREGATE_RECORD_LIMIT')
    result, seen, total = [], set(), 0
    for row in sorted(selected, key=lambda x: x['path']):
        raw = read_blob(api, row, core, core.MAX_PROPOSAL)
        total += len(raw)
        core.need(total <= MAX_TOTAL_RECORDS, 'AGGREGATE_RECORD_LIMIT')
        value = core.load_json(raw)
        core.need(type(value) is dict, 'PROPOSAL_SCHEMA')
        if value.get('schema') == 'ndx12.community-intake.v1':
            core.need(row['sha'] == LEGACY_15 and value.get('bundle_sha256') == LEGACY_15_BUNDLE,
                      'AGGREGATE_LEGACY_RECORD')
            value = dict(value, schema='ndx12.community-intake.v2', pci='10de:2882')
        core.validate_proposal(value)
        core.need(value['claimed_version'] == version and
                  core.record_folder(value) + '/record.json' == row['path'], 'AGGREGATE_RECORD_PATH')
        core.need(value['issue'] not in seen, 'AGGREGATE_DUPLICATE')
        seen.add(value['issue'])
        result.append(value)
    return result


def basename(version):
    """Keep the original curated v0.1.4 report outside automatic ownership."""
    return version + ('-intake-data.md' if version == 'v0.1.4' else '-submitted-data.md')


def markers(key):
    """Build fixed-format markers from validated catalogue/path keys only."""
    return ('<!-- ndx12:' + key + ':start -->', '<!-- ndx12:' + key + ':end -->')


def wrap(content, key):
    """Wrap generated bytes while leaving space for separate owner annotations."""
    start, end = markers(key)
    return (start + '\n').encode() + content.rstrip(b'\n') + ('\n' + end + '\n').encode()


def replace_region(raw, content, previous, key, core):
    """Preserve outside bytes and refuse unreviewed edits in generated content."""
    start, end = (x.encode() for x in markers(key))
    core.need(len(raw) <= MAX_DOCUMENT and raw.count(start) == raw.count(end) == 1,
              'AGGREGATE_MARKERS')
    begin, stop = raw.index(start), raw.index(end) + len(end)
    core.need(begin < raw.index(end), 'AGGREGATE_MARKERS')
    core.need(raw[begin:stop] == wrap(previous, key).rstrip(b'\n'), 'AGGREGATE_EDITED')
    updated = raw[:begin] + wrap(content, key).rstrip(b'\n') + raw[stop:]
    core.need(len(updated) <= MAX_DOCUMENT, 'AGGREGATE_DOCUMENT_LIMIT')
    return updated


def document_set(version, proposals, core):
    """Return only aggregate documents; never regenerate old per-Issue data/charts."""
    if not proposals:
        return {}
    report = load('community_version_report')
    report.core = core
    output = report.render(version, proposals, [p['issue'] for p in proposals])
    result = {}
    for path, raw in output.items():
        if path == core.ROOT + version + '-submitted-data.md':
            result[core.ROOT + basename(version)] = (raw, 'aggregate:' + version)
        elif path.endswith('/' + version + '/README.md'):
            target = path if version != 'v0.1.4' else path[:-len('README.md')] + 'intake-README.md'
            raw = raw.replace((version + '-submitted-data.md').encode(), basename(version).encode())
            result[target] = (raw, 'gpu:' + target[len(core.ROOT):-len('/README.md')]
                              if version != 'v0.1.4' else 'gpu:' + target[len(core.ROOT):])
    return result


def overview(version, proposals, prefix, core):
    """Build the generated table/link block, without owner acceptance decisions."""
    report = load('community_version_report')
    report.core = core
    proposals = sorted(proposals, key=lambda p: (report.gpu_name(p), p['issue']))
    ready = sum(p['state'] == 'DATA_READY' for p in proposals)
    contexts = [core.memory_backing(p)['native_dx12']['backing']
                for p in proposals if p['state'] == 'DATA_READY']
    backing = ('SYSMEM (system-memory buffers, not VRAM)' if contexts and
               all(x == 'SYSMEM' for x in contexts) else 'UNKNOWN (release evidence NOT_RECORDED)')
    table = report.overview(version, proposals, prefix).replace(version + '-submitted-data.md', basename(version))
    return (f'{len(proposals)} submissions checked for **{version} / {core.catalog()[version]["package_id"]}**. '
            f'{ready} matching exports have measurements; refused submissions contribute no numeric results.\n\n' +
            table + '\n\n**[View charts and extracted benchmark measurements](' + prefix + basename(version) +
            f')** — {ready} submission-specific charts and complete available median tables, with sources and caveats.\n\n' +
            'These are **reported export statuses**, not independently repeated GPU qualifications. '
            'Original GPU receipts are unavailable. No overall ranking or owner acceptance is implied.\n\n' +
            '**Native DX12 memory backing: ' + backing + '**. Vulkan memory backing: **NOT_RECORDED**.\n').encode()


def update_overview(raw, version, proposals, previous, prefix, core):
    """Update one release block or insert a new, separate release section."""
    key = 'overview:' + version
    start, end = (x.encode() for x in markers(key))
    content = overview(version, proposals, prefix, core)
    if start in raw or end in raw:
        core.need(previous, 'AGGREGATE_SOURCE_MISSING')
        return replace_region(raw, content, overview(version, previous, prefix, core), key, core)
    core.need(not previous, 'AGGREGATE_MARKERS')
    heading = ('## Additional community intake — ' if version == 'v0.1.4' else
               '## Community Benchmark Data — ') + version
    block = ('\n' + heading + '\n\n').encode() + wrap(content, key) + b'\n'
    position = raw.find(b'\n## ')
    position = len(raw) if position < 0 else position
    updated = raw[:position] + block + raw[position:]
    core.need(len(updated) <= MAX_DOCUMENT, 'AGGREGATE_DOCUMENT_LIMIT')
    return updated


def derive(proposal, api, entries, files, core):
    """Add one release refresh to the same draft; return permitted modified paths."""
    version = proposal['claimed_version']
    if version is None:
        return set()
    core.need(version in core.catalog() and re.fullmatch(r'v[0-9]+\.[0-9]+\.[0-9]+', version),
              'AGGREGATE_VERSION')
    previous = records(api, entries, version, core)
    core.need(all(p['issue'] != proposal['issue'] for p in previous), 'AGGREGATE_DUPLICATE')
    core.need(len(previous) < MAX_RECORDS, 'AGGREGATE_RECORD_LIMIT')
    combined = previous + [proposal]
    expected = document_set(version, previous, core)
    generated = document_set(version, combined, core)
    by_path = {row['path']: row for row in entries}
    modified = set()
    for path, (content, key) in generated.items():
        if path in by_path:
            core.need(path in expected, 'AGGREGATE_COLLISION')
            old = read_blob(api, by_path[path], core, MAX_DOCUMENT)
            updated = replace_region(old, content, expected[path][0], key, core)
            if updated != old:
                files[path] = updated
                modified.add(path)
        else:
            core.need(path not in expected, 'AGGREGATE_SOURCE_MISSING')
            files[path] = wrap(content, key)
    for path, prefix in [('Experiment Results/README.md', 'Community/'),
                         ('Experiment Results/Community/README.md', '')]:
        files[path] = update_overview(files[path], version, combined, previous, prefix, core)
    return modified


def source_signature(entries, version, core):
    """Identify aggregate/record source drift for strict orphan recovery."""
    if version is None:
        return []
    pattern = re.compile(re.escape(core.ROOT) + r'(?:[A-Za-z0-9_]+/){1,2}' +
                         re.escape(version) + r'/issue-[1-9][0-9]*/record\.json')
    return sorted((r['path'], r.get('sha'), r.get('mode')) for r in entries
                  if pattern.fullmatch(r['path']) or r['path'] == core.ROOT + basename(version) or
                  (r['path'].startswith(core.ROOT) and r['path'].endswith(('/' + version + '/README.md', '/' + version + '/intake-README.md'))))


def verify(root, core=None):
    """Read-only consistency check suitable for an owner-run pre-merge verification."""
    core = core or load('community_intake')
    root = Path(root).resolve()
    community = root / core.ROOT
    core.need(community.is_dir() and not community.is_symlink() and
              root in community.resolve().parents, 'AGGREGATE_LOCAL_INPUT')
    paths = community.rglob('record.json')
    total = 0
    count = 0
    versions = set()
    rows, blobs = [], {}
    for path in paths:
        core.need(not path.is_symlink() and root in path.resolve().parents, 'AGGREGATE_LOCAL_ALIAS')
        name = path.relative_to(root).as_posix()
        match = re.fullmatch(re.escape(core.ROOT) + r'(?:[A-Za-z0-9_]+/){1,2}'
                             r'(v[0-9]+\.[0-9]+\.[0-9]+)/issue-[1-9][0-9]*/record\.json', name)
        if not match:
            continue
        count += 1
        total += path.stat().st_size
        core.need(count <= 128 and total <= 16 * 1024 * 1024 and
                  path.stat().st_size <= core.MAX_PROPOSAL, 'AGGREGATE_RECORD_LIMIT')
        raw = path.read_bytes()
        oid = blob_id(raw)
        blobs[oid] = raw
        rows.append({'path': name, 'sha': oid, 'type': 'blob', 'mode': '100644'})
        versions.add(match[1])
    class Local:
        def get(self, endpoint):
            raw = blobs[endpoint.rsplit('/', 1)[1]]
            return {'sha': blob_id(raw), 'encoding': 'base64', 'size': len(raw),
                    'content': base64.b64encode(raw).decode()}
    def local_file(name):
        path = root / name
        core.need(path.is_file() and not path.is_symlink() and root in path.resolve().parents and
                  path.stat().st_size <= MAX_DOCUMENT, 'AGGREGATE_LOCAL_FILE')
        return path.read_bytes()
    # Generated release blocks must not disappear from checking when the last
    # source record is removed. Curated v0.1.4 pages have no such markers.
    managed = re.compile(
        rb'<!-- ndx12:(?:overview|aggregate):(v[0-9]+\.[0-9]+\.[0-9]+):(?:start|end) -->|'
        rb'<!-- ndx12:gpu:[A-Za-z0-9_/]+/(v[0-9]+\.[0-9]+\.[0-9]+)'
        rb'(?:/intake-README\.md)?:(?:start|end) -->')
    documents = list(community.glob('v*-data.md'))
    core.need(len(documents) <= 32, 'AGGREGATE_DOCUMENT_LIMIT')
    for version in core.catalog():
        suffix = '/intake-README.md' if version == 'v0.1.4' else '/README.md'
        for gpu in core.GPUS:
            path = community / (gpu + '/' + version + suffix)
            if path.exists() or path.is_symlink():
                documents.append(path)
    core.need(len(documents) <= 512, 'AGGREGATE_DOCUMENT_LIMIT')
    for name in list(('Experiment Results/README.md', core.ROOT + 'README.md')) + [
            p.relative_to(root).as_posix() for p in documents]:
        for match in managed.finditer(local_file(name)):
            versions.add((match[1] or match[2]).decode('ascii'))
    for version in sorted(versions):
        core.need(version in core.catalog(), 'AGGREGATE_VERSION')
        proposals = records(Local(), rows, version, core)
        core.need(proposals, 'AGGREGATE_SOURCE_MISSING')
        for path, (content, key) in document_set(version, proposals, core).items():
            raw = local_file(path)
            replace_region(raw, content, content, key, core)
        for path, prefix in [('Experiment Results/README.md', 'Community/'),
                             ('Experiment Results/Community/README.md', '')]:
            content = overview(version, proposals, prefix, core)
            replace_region(local_file(path), content, content, 'overview:' + version, core)
    return {'status': 'AGGREGATES_CURRENT', 'versions': sorted(versions)}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--verify-root', type=Path, required=True)
    args = parser.parse_args()
    core = load('community_intake')
    try:
        result = verify(args.verify_root, core)
    except core.Refused as error:
        print(json.dumps({'status': 'MANUAL_REVIEW', 'reason': str(error)}))
        raise SystemExit(2) from None
    except (OSError, KeyError, TypeError, ValueError, RecursionError):
        print(json.dumps({'status': 'MANUAL_REVIEW', 'reason': 'AGGREGATE_LOCAL_INPUT'}))
        raise SystemExit(2) from None
    print(json.dumps(result, sort_keys=True))
